/// <summary>
/// MPJ_30779_PaymentPlus
/// User Story 95329: P+ Large File Fix, Temporary fix until MS fixes it
/// Creating a new method for LedgerJournalMultiPost to create a new batch job for multithread journal posting
/// </summary>
[ExtensionOf(classStr(LedgerJournalMultiPost))]
final class METLedgerJournalMultiPost_Extension
{
}

Method.Source:
    /// <summary>
    /// Post a single journal.
    /// </summary>
    /// <param name = "_ledgerJournalTable">Identifies the journal to post, there should be only one after all approved journal lines moved into one single journal for Payments Plus.</param>
    /// <remarks>
    /// This method allows the user to run the posting of a single journal in batch and the ability
    /// to split that journal into smaller journals for better performance.
    /// </remarks>
    public static void METSingleJournalPostBatch(LedgerJournalTable _ledgerJournalTable)
    {
        // Creates instance of LedgerJournalMultiPost
        LedgerJournalMultiPost ledgerJournalMultiPost = LedgerJournalMultiPost::METInitLedgerJournalMultiPost(_ledgerJournalTable);

        // Creates the new batch job
        ledgerJournalMultiPost.METCreateLedgerJournalMultiPostBatch(_ledgerJournalTable);        
    }

    /// <summary>
    /// Copied from LedgerJournalMultiPost\singleJournalPost without the prompt and runOperation.
    /// Initialise LedgerJournalMultiPost and create the record in ledgerJournalParmPost with transfer errors
    /// </summary>
    /// <param name = "_ledgerJournalTable">Identifies the journal to post, there should be only one after all approved journal lines moved into one single journal for Payments Plus.</param>
    /// <returns></returns>
    public static LedgerJournalMultiPost METInitLedgerJournalMultiPost(LedgerJournalTable _ledgerJournalTable)
    {
        LedgerJournalMultiPost ledgerJournalMultiPost = new LedgerJournalMultiPost();

        ledgerJournalMultiPost.initParmId();

        ledgerJournalMultiPost.parmIsMultiSelectPostEnabled(false);
        ledgerJournalMultiPost.parmIsSingleJournalPostEnabled(true);

        ParmBuffer parmBuffer = ledgerJournalMultiPost.defaultParmBuffer();
        ledgerJournalMultiPost.insert(_ledgerJournalTable, parmBuffer);
        /*
        if (!ledgerJournalMultiPost.prompt())
        {
            return;
        }

        ledgerJournalMultiPost.runOperation();
        */
        // Updates created ledgerJournalParmPost records to force transfer errors Yes
        ttsbegin;
        LedgerJournalParmPost   ledgerJournalParmPost;
        update_recordset ledgerJournalParmPost
            setting TransferErrors = NoYes::Yes
            where ledgerJournalParmPost.parmid == ledgerJournalMultiPost.parmId();

        ttscommit;

        return ledgerJournalMultiPost;
    }

    /// <summary>
    /// New method to create a LedgerJournalMultiPost batch job to make sure multithread journal posting is executed
    /// </summary>
    /// <param name = "_ledgerJournalTable">Journal to be posted</param>
    public void METCreateLedgerJournalMultiPostBatch(LedgerJournalTable _ledgerJournalTable)
    {
        const BatchCaption batchCaption = '8000 – PaymentsPlus Post Settled Payment Journal %1';
        const BatchGroupId batchGroup = 'PPLUS';
        
        // Create the multithread posting batch
        BatchHeader batchHeader = Batchheader::construct();
        BatchInfo objBatchInfo;
        SysRecurrenceData sysRecurrenceData;

        // Set the recurrence data
        sysRecurrenceData = SysRecurrence::defaultRecurrence();
        // Set end after 1
        sysRecurrenceData = SysRecurrence::setRecurrenceEndAfter(sysRecurrenceData, 1);

        // set the batch task class to LedgerJournalMultiPost
        objBatchInfo = this.batchInfo();
        objBatchInfo.parmRetriesOnFailure(0);
        objBatchInfo.parmCaption(strFmt(batchCaption, _ledgerJournalTable.JournalNum)); // Description Batch Job
        objBatchInfo.parmBatchExecute(NoYes::Yes);
        objBatchInfo.parmRecurrenceData(sysRecurrenceData);

        batchHeader.addTask(this);
        batchHeader.parmRecurrenceData(sysRecurrenceData);
        batchHeader.parmCritical(NoYes::Yes);
        batchHeader.parmBatchJobPriorityIsOverridden(true);
        batchHeader.parmBatchJobPriority(BatchSchedulingPriority::Critical);
        batchHeader.parmBatchGroup(batchGroup);

        // Set the batch alert configurations
        batchHeader.parmAlerts(NoYes::No, NoYes::Yes, NoYes::No, NoYes::No, NoYes::No);
        batchHeader.save();
    }
